    // [regular expression, replacement] — replacement may be a function
    patterns: [
      [/^Card: (.+)\. Tap to flip\.$/, "Carta: $1. Tocca per girarla."],
      [/^([A-Z]{1,3}) row$/, "riga $1"],
      [/^You chose “(.+)”\.$/, "Hai scelto “$1”."],
      [/^(\d+)\. (.+)$/, (m, n, rest, T) => { const t = T(rest); return t ? `${n}. ${t}` : null; }],
      [/^Which of these sounds do you hear in “(.+)”\?$/, "Quale di questi suoni senti in “$1”?"],
      [/^Which is the correct transcription of “(.+)”\?$/, "Qual è la trascrizione corretta di “$1”?"],
      [/^(voiced|voiceless) ([a-z-]+) ((?:lateral )?[a-z]+)$/, (m, v, pl, mn) => PH[mn] && PH[pl] ? `${PH[mn]} ${PH[pl]} ${PH[v]}` : null],
      [/^Which symbol represents an? (.+)\?$/, (m, d, T) => { const t = T(d); return t ? `Quale simbolo rappresenta una ${t}?` : null; }],
      [/^(short|long), (.+), (.+), (.+)$/, (m, ...p) => { const t = p.slice(0, 4).map(x => PH[x]); return t.every(Boolean) ? t.join(", ") : null; }],
      [/^Which vowel is (.+)\?$/, (m, d, T) => { const t = T(d); return t ? `Quale vocale è ${t}?` : null; }],
      [/^The sound (\/.+\/)$/, "Il suono $1"],
      [/^(\d+) exercises shown$/, "$1 esercizi mostrati"], [/^(\d+) items$/, "$1 elementi"],
      [/^Name, class, date · duration (.+)$/, "Nome, classe, data · durata $1"],
      [/^(.+?) – (.+)$/, (m, a, b, T) => { const ta = T(a), tb = /^\d+$/.test(b) ? b : T(b); return ta && tb ? `${ta} – ${tb}` : null; }],
      [/^(.+) · Language Dojo$/, (m, rest, T) => rest.split(" · ").map(p => T(p) || p).join(" · ") + " · Language Dojo"]
    ]
